let controls = global.get('controls', 'memoryOnly') || {};
let describe = global.get('describe', 'memoryOnly') || {};
let pilot = ['pow','mode','stemp','f_rate','f_dir'];
let path = msg.topic.split('/');
let key = path.pop();
let device = path.pop();
let value = msg.payload.toString();

if(pilot.indexOf(key) != -1) {
    for (const host in controls) {
        if (device === controls[host]['id']['raw']) {
            let label = key;

            // pilot by full name (mode, f_rate, f_dir) ?
            if (typeof describe[key] === 'object') {
                for (const src in describe[key]) {
                    if (describe[key][src] === value) {
                        value = src;
                    }
                }
            }

            let raw = value;
            let full = value;
            let unit = '';

            // get readbale label
            if (typeof describe.label[label] == 'string') {
                label = describe.label[label];
            }
            // get readbale unit
            if (typeof describe.unit[key] == 'string') {
                unit = describe.unit[key];
            }

            // Convert numeric value to number
            if (!isNaN(value) && isFinite(Number(value))) {
                value = Number(value);
            }

            if (key === 'pow') {
                full = describe.pow[raw];
            }
            else if (key === 'mode') {
                full = describe.mode[raw];
            }
            else if (key === 'stemp') {
                full = full + unit;
            }
            else if (key === 'f_rate') {
                full = describe.f_rate[raw];
            }
            else if (key === 'f_dir') {
                full = describe.f_dir[raw];
            }

            controls[host][key] = {
                'unit': unit,
                'label': label,
                'raw': raw,
                'value': value,
                'full': full
            };

            global.set('controls', controls, 'memoryOnly');

            msg.topic = host;
            msg.payload = controls;

            return msg;
        }
    }
}

return;
